  a2Orders().forEach(function(x){ if(!(x.createdAt >= start && x.createdAt < end)) return; var k = Math.floor((x.createdAt - start) / A2.D), s = a2O(x).ost;
    if(s === 'DELIVERED' || s === 'PARTIALLY_DELIVERED') o.del[k]++; else if(s === 'RETURNED') o.ret[k]++; else if(s === 'CANCELLED') o.can[k]++; else if(s === 'HANDED_OVER' || s === 'IN_TRANSIT') o.cour[k]++; else o.wait[k]++; });
