function a3CourDays(){ var by = {}; a2Orders().forEach(function(o){ var a = a2O(o); if(!o.deliveredAt || !a.cour || o.deliveredAt < Date.now() - 30 * A2.D) return; var b = by[a.cour] = by[a.cour] || []; b.push((o.deliveredAt - (a.handedAt || a.pickedAt || o.createdAt)) / A2.D); }); var out = {}; Object.keys(by).forEach(function(k){ out[k] = by[k].reduce(function(s, x){ return s + x; }, 0) / by[k].length; }); return out; }
