/* waterfall: items [label, labelBn, value, 't'|'f' for totals] */
function a3Water(items){
  var cur = 0, peak = 0; items.forEach(function(x, i){ if(i === 0 || x[3]) cur = x[2]; else cur += x[2]; peak = Math.max(peak, cur, x[2]); }); var sc = (peak || 1) * 1.14; cur = 0;
  var cols = items.map(function(x, i){ var v = x[2], tot = !!x[3], from, to;
    if(i === 0 || tot){ from = 0; to = v; } else { from = cur; to = cur + v; } cur = to;
    var lo = Math.max(0, Math.min(from, to)), hi = Math.max(0, from, to), cls = tot ? (x[3] === 'f' ? 'fin' : 'tot') : i === 0 ? 'first' : v >= 0 ? 'pos' : 'neg';
    var lbl = (v < 0 ? '−' : tot || i === 0 ? '' : '+') + a3K(Math.abs(v));
    return '<div class="a3-wc ' + cls + '" data-tip="' + esc('<b>' + L(x[0], x[1]) + '</b><span>' + (v < 0 ? '−' : tot || i === 0 ? '' : '+') + a2tk(Math.abs(v)) + '</span>') + '"><div class="a3-wp"><span class="a3-wv a3-num" style="bottom:' + (hi / sc * 100).toFixed(1) + '%">' + lbl + '</span><i style="bottom:' + (lo / sc * 100).toFixed(2) + '%;height:' + Math.max(.8, (hi - lo) / sc * 100).toFixed(2) + '%"></i></div><em>' + Le(x[0], x[1]) + '</em></div>'; }).join('');
  return '<div class="a3-water" style="--n:' + items.length + '">' + cols + '</div>';
}

