function a3Mini(cod){ var t = cod.reduce(function(s, c){ return s + c.v; }, 0) || 1, C = ['#1F6B54', '#6FA08D', '#C9A14A', '#4C6A92', '#B9BDB8']; return '<span class="a3-mini">' + cod.map(function(c, i){ return '<i style="flex:' + c.v + ';background:' + C[i % C.length] + '" data-tip="' + esc('<b>' + c.name + '</b><span>' + a2tk(c.v) + ' · ' + c.n + L(' parcels', 'টা') + '</span>') + '"></i>'; }).join('') + '</span><span class="a3-minik">' + cod.slice(0, 3).map(function(c, i){ return '<span><i style="background:' + C[i] + '"></i>' + esc(c.name) + '</span>'; }).join('') + '</span>'; }
